	sections = {
		{
			title = "Обзор",
			text = [=[Холм Нефритового Пламени лежит на северо-западе Оскверненного леса. Это второй лагерь {link:satyrs}сатир{/link}ов Нефритового Пламени, и более опасный. Призыватели ада, предатели и обманщики собираются здесь под началом сатира {link:xavaric}Ксаварик{/link}а, который получал плоды оскверненного лунного колодца в {link:ruins-of-constellas}Констеллас{/link}е. Сатиры Холма кормятся порчей лесных существ. У них нашли деревянную флейту, вырезанную из павшего древнего хранителя, и она поведала друидам, что жестокость сатиров дотянулась даже до защитников леса.]=],
		},
	},
})

Translate("ruRU", "deadwood-village", {
