})

Translate("ruRU", "felpaw-village", {
	title = "Деревня Сквернолапов",
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Сквернолапов — северный лагерь {link:furbolgs}фурболг{/link}ов Мертвого Леса, в холмах ниже входа в {link:timbermaw-hold}Крепость Древобрюхов{/link}. Здесь под властью вождя Кровавой Пасти живут стражи берлог, мстители и шаманы. {link:timbermaw-furbolgs}Древобрюхи{/link}, которые стерегут Крепость, смотрят на нее сверху с печалью, ибо ее жители — их собственные братья. В лагере стоит котел с зеленым зловонным варевом. Видели, как фурболги Зимней Спячки из дальних снегов проходят через Крепость, и некоторые подозревают, что варево несут к ним на север.]=],
		},
	},
})

Translate("ruRU", "timbermaw-hold", {
	title = "Крепость Древобрюхов",
