		{
			title = "Значение",
			text = [=[Эридан первой в Изумрудном {link:krueg-skullsplitter}Круг{/link}е увидела, что {link:satyrs}сатир{/link}ы Оскверненного леса не просто жестоки, а действуют сообща. Она узнала, что лагерь на юге, которым правил {link:xavathras}Ксаватрас{/link}, растил оскверненный лунный колодец ради сатира {link:xavaric}Ксаварик{/link}а на севере. Она подозревает, что за ними стоит нечто еще большее. Ее знания простираются и далеко за пределы Оскверненного леса: путники ищут ее ради тайн стихий, которые мало кому ведомы.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она послала бойцов против {link:satyrs}сатир{/link}а {link:xavathras}Ксаватрас{/link}а в Руинах {link:ruins-of-constellas}Констеллас{/link}а и против сатира {link:xavaric}Ксаварик{/link}а на Холме Нефритового Пламени.
• Она освободила дух древнего хранителя, которого сатиры заточили во флейте.
• Она научила делать тотем, способный сломить ауру огненного элементаля {link:blazerunner}Огнебег{/link}а в {link:un-goro-crater}Кратере Ун'Горо{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Сатиры Нефритового Пламени",
			hint = "Сразите владык сатиров Нефритового Пламени.",
			text = [=[Когда пал {link:xavathras}Ксаватрас{/link}, Эридан не радовалась. Она почувствовала, что этот {link:satyrs}сатир{/link} — лишь часть большего замысла. Правда открывалась медленно: Ксаватрас взрастил оскверненный лунный колодец и отправлял его плоды на север, где их ждал {link:xavaric}Ксаварик{/link}. Когда были убиты оба, она взмолилась, чтобы богиня Элуна хранила тех, кто сделал это дело. Исцеление, знала она, займет куда больше времени, чем убийство.]=],
		},
		{
			title = "Плененный хранитель",
			hint = [=[Принесите друиду флейту, найденную у сатира, и благословенную воду Храма Луны.]=],
			text = [=[Флейта, которую носил {link:xavaric}Ксаварик{/link}, была вырезана из одного из древней-хранителей, оберегавших ночных эльфов. Магией Скверны дух хранителя привязали к дереву и терзали там. Эридан едва могла держать флейту в руках. Она омыла ее в благословенной воде богини Элуны, и связь разорвалась. Она верила, что флейта, если сыграть на ней в священном месте, сможет призвать духов древних хранителей, которые все еще блуждают по лесу.]=],
		},
		{
			title = "Поручение незнакомца",
			hint = "Придите к Эридан от имени странника из Кратера Ун'Горо.",
			text = [=[Незнакомец в {link:un-goro-crater}Кратере Ун'Горо{/link} произнес ее имя, хотя мало что еще мог вспомнить. Эридан не знала его, но знала его цель. Она собрала когти и сердце древня из Железнолесья и отправила их вместе с Книгой Аквора к кругу камней в {link:tanaris}Танарисе{/link}, где можно призвать водного элементаля Аквементаса, чтобы тот выковал из них тотем.]=],
		},
	},
	mentions = {
		{
			text = [=[Флейта {link:satyrs}сатир{/link}а {link:xavaric}Ксаварик{/link}а]=],
		},
		{ text = "Память странника {link:linken}Линкен{/link}а" },
		{ text = "Серебряное сердце" },
		{ text = "Аквементас" },
		{ text = "Порча {link:satyrs}сатир{/link}ов Нефритового Пламени" },
		{ text = "Древние хранители в оковах Скверны" },
		{ text = "Очищено!" },
		{ text = "Новая порча" },
	},
	bonds = {
		{ id = "xavathras", name = "Ксаватрас", note = "сатир, которого убили по ее воле" },
		{ id = "xavaric", name = "Ксаварик", note = "владыка сатиров севера" },
		{ id = "arei", name = "Арей", note = "дух древней хранительницы леса" },
		{ id = "greta-mosshoof", name = "Грета Мшистое Копыто", note = "из того же круга" },
	},
})

Translate("ruRU", "greta-mosshoof", {
	title = "Грета Мшистое Копыто",
	subtitle = "Друид Изумрудного Круга",
	found = "Изумрудное святилище, на юге Оскверненного леса",
	hint = [=[Найдите друида Изумрудного Круга, который ведет войну с Советом Теней.]=],
	allegiance = "Изумрудный Круг · Круг Кенария",
	aliases = { "Грета" },
	sections = {
		{
			title = "Обзор",
			text = [=[Грета Мшистое Копыто — друид Изумрудного {link:krueg-skullsplitter}Круг{/link}а, и молится она Матери-Земле. Там, где другие в ее круге стремятся исцелить лес, она взялась ударить по причине его недуга. Ее враг — {link:shadow-council}Совет Теней{/link} в {link:jaedenar}Джеденар{/link}е, и она намерена отсечь ему голову.]=],
		},
		{
			title = "Значение",
			text = [=[Грета замышляет и направляет войну круга против {link:jaedenar}Джеденар{/link}а. Она понимает, что с {link:shadow-council}Совет{/link}ом нельзя сражаться вслепую, и ей хватает терпения узнать, прежде чем ударить. Она хранит и большую надежду: собрать лекарство, которое однажды исцелит деревья и существ Оскверненного леса.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она испытала решимость тех, кто пришел помочь ей против сектантов {link:jaedenar}Джеденар{/link}а.
• По ее воле духи воды очистили оскверненную воду лунного колодца Джеденара.
• Она заглянула прорицанием в Оплот Теней и узнала, кто возглавляет {link:shadow-council}Совет{/link}.
• Она послала союзников против Владыки Теней {link:shadow-lord-fel-dan}Фел'дан{/link}а и его слуг.
• Она искала кровь зеленого дракона {link:morphaz}Морфаза{/link} для второго лекарства Оскверненного леса.]=],
		},
	},
	chapters = {
		{
			title = "Вода против огня",
			hint = [=[Отнесите воду из лунного колодца Джеденара на очищение и вылейте ее на жаровни Оплота Теней.]=],
			text = [=[{link:shadow-council}Совет{/link} {link:ogres}огр{/link}аждал {link:jaedenar}Оплот Теней{/link} чарами, которые горели в четырех жаровнях. Грета велела добыть воду из оскверненного лунного колодца в сердце Джеденара, а затем отправила ее на юг к старому другу — шаману, который живет у моря к югу от {link:ratchet}Кабестан{/link}а. Духи воды услышали шамана и благословили это дело. Очищенной водой пламя залили. Недолгое время, пока чернокнижники не восстановили свою защиту, Грета могла видеть, что творится в Оплоте.]=],
		},
		{
			title = "Голова змеи",
			hint = "Нанесите удар по смертному, который возглавляет Совет Теней.",
			text = [=[То, что увидела Грета, сказало ей: хитрого пути внутрь нет. {link:shadow-lord-fel-dan}Фел'дан{/link}, Владыка Теней, был тем смертным, что повелевал внизу, и именно он заключал договоры с Легионом. Она послала союзников прямо к нему. Когда его голову принесли ей, она восславила Мать-Землю. Она надеялась, что без него {link:shadow-council}Совет{/link} обратится против самого себя.]=],
		},
		{
			title = "Второе лекарство",
			hint = "Принесите ей кровь дракона Морфаза из затонувшего храма.",
			text = [=[Говорят, что зеленый дракон {link:morphaz}Морфаз{/link} неуязвим для любого яда и любой болезни, и многие друиды погибли, чтобы это узнать. Грета хотела получить его кровь. Когда кровь принесли, она едва могла поверить. Понадобится целая жизнь, сказала она, чтобы исправить случившееся в Оскверненном лесу, но наконец у круга появилось средство начать.]=],
		},
	},
	mentions = {
		{ text = "Силы {link:jaedenar}Джеденар{/link}а" },
		{ text = "Сбор оскверненной воды" },
		{ text = "В поисках помощи духов" },
		{
			text = [=[Очищенная вода возвращается в {link:felwood}Оскверненный лес{/link}]=],
		},
		{ text = "Погасить пламя защиты" },
		{ text = "Последний удар" },
		{ text = "Кровь дракона {link:morphaz}Морфаз{/link}а" },
	},
	bonds = {
		{ id = "shadow-lord-fel-dan", name = "Владыка Теней Фел'дан", note = "голова змеи" },
		{ id = "eridan-bluewind", name = "Эридан Синий Ветер", note = "из того же круга" },
		{ id = "morphaz", name = "Морфаз", note = "тот, чью кровь она искала" },
	},
})

Translate("ruRU", "lord-banehollow", {
	title = "Лорд Бейнхоллоу",
	subtitle = "Повелитель ужаса из Джеденара",
	found = "Глубины Оплота Теней, в Джеденаре",
	hint = [=[Облекитесь в тень и ищите повелителя ужаса на самом дне Джеденара.]=],
	allegiance = "Пылающий Легион · Совет Теней",
	aliases = { "Бейнхоллоу" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лорд Бейнхоллоу — повелитель ужаса, который держит двор в глубинах {link:jaedenar}Джеденар{/link}а, оплота {link:shadow-council}Совета Теней{/link}. Он стар, терпелив и жесток. Чернокнижники Совета приходят и уходят перед ним, и лишь те, кто облечен в тень самого Совета, могут приблизиться к нему невредимыми.]=],
		},
		{
			title = "Значение",
			text = [=[Бейнхоллоу — демон, стоящий за смертными чернокнижниками {link:jaedenar}Джеденар{/link}а, и соперники у него есть даже среди собственного рода. Первый из них — лорд Хел'нурат, который правит владением Ксорот за пределами этого мира и разводит там прославленных коней погибели. Бейнхоллоу хранит запас звездной пыли из мира Ксорот, и чернокнижникам, которые хотят открыть путь в то царство, приходится торговаться с ним за нее.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он правит из глубин Оплота Теней.
• Он раскрыл, что его слуга {link:ulathek}Улатек{/link} — лазутчик, которого прислал Хел'нурат.
• Он продает звездную пыль мира Ксорот через своего слугу Ур'дана.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, как долго Бейнхоллоу обитает в Оскверненном лесу и какая сделка связывает его с {link:shadow-council}Совет{/link}ом Теней.]=],
		},
	},
	chapters = {
		{
			title = "Гость в Джеденаре",
			hint = [=[Придите в Джеденар под личиной, которую дают теневые зелья из Пылающих степей.]=],
			text = [=[Гоблин {link:gorzeeki-wildeyes}Горзики Дикоглаз{/link} варит зелья, которые позволяют выпившему сойти за одного из {link:shadow-council}Совет{/link}а Теней. Те, кто их пьет, могут пройти через {link:jaedenar}Джеденар{/link} и предстать перед лордом Бейнхоллоу. Он встречает их без тепла. Его терпение, говорит он, длится тысячелетиями, и все же им достанется от него не больше мгновения.]=],
		},
		{
			title = "Сердце предателя",
			hint = "Докажите повелителю ужаса свою службу.",
			text = [=[{link:ulathek}Улатек{/link} пресмыкался перед хозяином, а сам плел заговор вместе с лордом Хел'нуратом, который надеялся забрать себе власть над Оскверненным лесом. Бейнхоллоу знал. Он хотел, чтобы слуге об этом сказали, и хотел видеть его страх. Потом он пожелал получить сердце, которому собирался дать погнить неделю, прежде чем съесть.]=],
		},
		{
			title = "Звездная пыль мира Ксорот",
			hint = "Купите звездную пыль мира Ксорот у слуги повелителя ужаса.",
			text = [=[Бейнхоллоу сразу догадался, зачем чернокнижнику звездная пыль: чтобы открыть портал во владения его соперника и увести одного из тамошних коней погибели. Эта мысль его не встревожила. Он позволил своему слуге Ур'дану продать пыль — за плату. Она вернулась к гоблину {link:gorzeeki-wildeyes}Горзики{/link}, а от него попала к чернокнижнику {link:mor-zul-bloodbringer}Мор'зулу Вестнику Крови{/link}, которому была нужна для чернил.]=],
		},
	},
	mentions = {
		{ text = "Лорд Бейнхоллоу" },
		{
			text = [=[{link:illidan-stormrage}Предатель{/link} {link:ulathek}Улатек{/link}]=],
		},
		{ text = "Звездная пыль мира Ксорот" },
	},
	bonds = {
		{ id = "ulathek", name = "Улатек", note = "его вероломный слуга" },
		{ id = "gorzeeki-wildeyes", name = "Горзики Дикоглаз", note = "посылает к нему гостей" },
		{ id = "mor-zul-bloodbringer", name = "Мор'зул Вестник Крови", note = "получает его звездную пыль" },
		{ id = "shadow-lord-fel-dan", name = "Владыка Теней Фел'дан", note = "смертный владыка Совета, стоящий ниже него" },
	},
})

Translate("ruRU", "tichondrius", {
	title = "Тикондрус",
	subtitle = "Повелитель ужаса Пылающего Легиона",
	hint = "Узнайте, кто отравил северный лес Черепом колдуна Гул'дана.",
	allegiance = "Пылающий Легион",
	sections = {
		{
			title = "Обзор",
			text = [=[Тикондрус был повелителем ужаса, одним из натрезимов, служащих {link:burning-legion}Пылающему Легиону{/link}. В {link:third-war}Третью войну{/link} он был среди демонов, которые направляли {link:scourge}Плеть{/link} от имени Легиона, и отдавал приказы рыцарю смерти {link:arthas-menethil}Артасу Менетилу{/link}. Когда Легион пришел в {link:kalimdor}Калимдор{/link}, он принес в северный лес Череп колдуна {link:gul-dan}Гул'дана{/link} и отравил лес темной силой черепа. Этот лес — {link:felwood}Оскверненный лес{/link}. Там его и сразил {link:illidan-stormrage}Иллидан Ярость Бури{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Из всех демонов Третьей войны Тикондрус оставил самый глубокий след на самой земле. {link:archimonde}Архимонд{/link} пал у горы Хиджал, и его воинство было разбито, но порча, которую посеял Тикондрус, не умерла вместе с ним. Каждый безумный {link:furbolgs}фурболг{/link}, каждый пораженный порчей древень и каждый скверный лунный колодец Оскверненного леса — часть его наследия. Его смерть навсегда изменила и того, кто его убил: чтобы одолеть его, {link:illidan-stormrage}Иллидан{/link} принял в себя силу черепа, и собственный народ изгнал его за это.]=],
		},
		{
			title = "Плеть и Легион",
			text = [=[Король-лич создал {link:scourge}Плеть{/link}, но свободной он ее не создал. За ней надзирали повелители ужаса Легиона, и Тикондрус был среди них. После того как {link:arthas-menethil}Артас{/link} убил своего отца и всецело отдал себя Плети, Тикондрус испытал верность принца и дал ему поручения. Артас отнес останки некроманта {link:kel-thuzad}Кел'Тузада{/link} к Солнечному Колодцу королевства {link:quel-thalas}Кель'Талас{/link}, где Кел'Тузад был поднят как лич. Кел'Тузад, в свой черед, призвал в мир демона {link:archimonde}Архимонда{/link} в {link:dalaran}Даларане{/link}. Когда владыка Легиона наконец явился, Плеть исполнила свое назначение, и демоны обратились к {link:kalimdor}Калимдор{/link}у.]=],
		},
		{
			title = "Отравление леса",
			text = [=[Воинство, которое вел {link:archimonde}Архимонд{/link}, шло на гору Хиджал и Мировое Древо {link:nordrassil}Нордрассил{/link}. Тикондрус пришел в северные леса с Черепом колдуна {link:gul-dan}Гул'дан{/link}а — останками чернокнижника, который первым привязал {link:orcs}орк{/link}ов к Легиону. Череп все еще хранил многое от силы Скверны, которой владел Гул'дан, и Тикондрус обратил ее на то, чтобы осквернить леса вокруг. Деревья почернели, а воды испортились. Звери и {link:furbolgs}фурболг{/link}и обезумели. Инферналы падали с неба в огне, и древние хранители, которые стерегли лес, были уничтожены.]=],
		},
		{
			title = "Гибель повелителя ужаса",
			text = [=[{link:tyrande-whisperwind}Тиранда Шелест Ветра{/link} освободила узника {link:illidan-stormrage}Иллидан{/link}а из долгого заточения, чтобы он сражался с демонами. Иллидан узнал о черепе и отправился за ним. Он взял череп и поглотил его силу. Она изменила его: у него выросли рога и {link:ogres}огр{/link}омные темные крылья, и он сам стал отчасти демоном. Этой силой он сразил повелителя ужаса Тикондруса. Победа стоила ему всего остального. {link:malfurion-stormrage}Малфурион Ярость Бури{/link} не смог простить того, чем стал его брат, и изгнал его из лесов ночных эльфов.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не рассказывает, как Тикондрус завладел черепом и как долго он пробыл в лесу, прежде чем {link:illidan-stormrage}Иллидан{/link} нашел его.]=],
		},
	},
	chapters = {
		{
			title = "Память древних хранителей",
			hint = "Выведите дух древней хранительницы из оскверненного леса.",
			text = [=[Дух древней хранительницы {link:arei}Арей{/link} все еще помнит лес, каким он был до прихода Легиона. Она помнит инферналов, разрушение и хаос. Она помнит, что череп колдуна {link:gul-dan}Гул'дан{/link}а позаботился о том, чтобы в лесу не пощадили ничего. Даже будучи духом, она не может уйти от страданий этой земли. Она просит лишь вывести ее отсюда, чтобы обрести покой.]=],
		},
	},
	mentions = {
		{ text = "Дух древней хранительницы" },
