})

Translate("ruRU", "skull-of-gul-dan", {
	title = "Череп Гул'дана",
	aliases = { "череп Гул'дана" },
	sections = {
		{
			title = "Обзор",
			text = [=[Череп Гул'дана был черепом {link:orcs}орк{/link}а-чернокнижника {link:gul-dan}Гул'дана{/link}, основателя {link:shadow-council}Совета Теней{/link}. Он пережил гибель чернокнижника в Гробнице {link:sargeras}Саргерас{/link}а и сохранил многое от его силы Скверны. В {link:third-war}Третью войну{/link} повелитель ужаса {link:tichondrius}Тикондрус{/link} принес его в {link:kalimdor}Калимдор{/link} и с его помощью осквернил северный лес. {link:illidan-stormrage}Иллидан Ярость Бури{/link} отнял у него череп и поглотил его силу, и с нею стал существом, наполовину демоном.]=],
		},
		{
			title = "Его наследие",
			text = [=[Черепа больше нет, но дело его осталось. Отравленный им лес зовется Оскверненным. Духи древних хранителей помнят, что он не пощадил ничего, а друиды Изумрудного {link:krueg-skullsplitter}Круг{/link}а до сих пор борются с тем, что он оставил после себя.]=],
		},
	},
})

Translate("ruRU", "shadow-council", {
	title = "Совет Теней",
	aliases = { "Совет" },
	sections = {
		{
			title = "Обзор",
			text = [=[Совет Теней — тайный орден чернокнижников, служащих {link:burning-legion}Пылающему Легиону{/link}. Он родился среди {link:orcs}орк{/link}ов Дренора и пережил Орду, которой некогда правил. Сегодня его оплот — {link:jaedenar}Джеденар{/link} в {link:felwood}Оскверненном лесу{/link}, а его секты рассеяны по всему миру.]=],
		},
		{
			title = "Истоки",
			text = [=[Владыка демонов {link:kil-jaeden}Кил'джеден{/link} избрал чернокнижника {link:gul-dan}Гул'дана{/link} своим слугой среди {link:orcs}орк{/link}ов. Гул'дан собрал самых честолюбивых из собратьев-чернокнижников в тайный совет. Тот правил кланами орков из-за спины вождя-марионетки и привел их к тому, чтобы они испили кровь демона {link:mannoroth}Маннорота{/link}. Через колдуна Гул'дана он открыл {link:dark-portal}Темный портал{/link}.]=],
		},
		{
			title = "Падение",
			text = [=[В дни после {link:first-war}Первой войны{/link} Совет устроил свой оплот на {red:blackrock-spire}Вершине Черной горы{/red}. Там {link:orgrim-doomhammer}Оргрим Молот Рока{/link} обратился против него, перебил большинство его членов и взял в плен их главу. Позже {link:gul-dan}Гул'дан{/link} предал Орду и погиб. Считалось, что Совет умер вместе с ним.]=],
		},
		{
			title = "Наши дни",
			text = [=[Он не умер. В {link:jaedenar}Джеденар{/link}е орден возглавляет {link:shadow-lord-fel-dan}Владыка Теней Фел'дан{/link}, который заключает его договоры с Легионом, а в глубинах под ним держит двор повелитель ужаса. Совет винят во многих бедах в Оскверненном лесу и за его пределами. Его знак встречается среди чернокнижников {link:arathi-highlands}Нагорья Арати{/link}. В {link:orgrimmar}Оргриммар{/link}е его целям служат {link:burning-blade}Пылающий Клинок{/link} и секта Палящего Клинка, а Присягнувшие Тени из {link:blasted-lands}Выжженных земель{/link} — его наследники. {link:thrall}Тралл{/link} знает, что Совет жив, и намерен его найти.]=],
		},
	},
})

Translate("ruRU", "emerald-circle", {
	title = "Изумрудный Круг",
	sections = {
		{
			title = "Обзор",
			text = [=[Изумрудный Круг — братство друидов {link:cenarion-circle}Круга Кенария{/link}, которые посвятили себя Оскверненному лесу. {link:night-elves}Ночные эльфы{/link} и {link:tauren}таурен{/link}ы служат в нем вместе и равно рады друзьям {link:alliance}Альянс{/link}а и Орды. Из Изумрудного святилища они изучают порчу и пытаются обратить ее вспять.]=],
		},
		{
			title = "Их труд",
			text = [=[• Они сражаются с {link:satyrs}сатир{/link}ами Нефритового Пламени и с {link:shadow-council}Советом Теней{/link}, которые разносят и питают порчу.
• Они научились готовить мази, которые исцеляют оскверненные растения, но делятся этим знанием лишь с теми, кто себя проявит.
• Они ищут чистую воду и лекарство, которое сможет исцелить деревья и существ леса.
• Они изучают {link:furbolgs}фурболг{/link}ов Оскверненного леса и иных краев и безумие, которое их охватило.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, когда был основан Изумрудный Круг и кто возглавил его первым.]=],
		},
	},
})

Translate("ruRU", "deadwood-furbolgs", {
	title = "Фурболги Мертвого Леса",
	aliases = { "Мертвый Лес", "племя Мертвого Леса" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мертвый Лес — племя {link:furbolgs}фурболгов{/link} Оскверненного леса, которое Скверна довела до безумия. Они удерживают Деревню Мертвого Леса на юге леса и Деревню Сквернолапов на севере и нападают на всех, кто подходит близко.]=],
		},
		{
			title = "Безумие",
			text = [=[{link:timbermaw-furbolgs}Древобрюхи{/link} говорят, что {link:furbolgs}фурболг{/link}и Мертвого Леса не злы по природе. Это Скверна отравляет их разум, и этого уже не исправить. Их ритуальные тотемы смердят тлением и отчаянием. В их северном лагере в котле кипит зеленое гниющее варево, и, возможно, оно разносит безумие на фурболгов Зимней Спячки из {link:winterspring}Зимних Ключей{/link}.]=],
		},
		{
			title = "Их вожди",
			text = [=[• {b}{link:overlord-ror}Властитель Рор{/link}{/b} правит Деревней Мертвого Леса на юге.
• {b}Вождь Кровавая Пасть{/b} правит лагерем близ Крепости Древобрюхов на севере.]=],
		},
	},
})

Translate("ruRU", "timbermaw-furbolgs", {
	title = "Фурболги-Древобрюхи",
	aliases = { "Древобрюхи", "племя Древобрюхов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Древобрюхи — единственное племя {link:furbolgs}фурболгов{/link}, избежавшее порчи. Они живут в Крепости Древобрюхов, в туннелях между {link:felwood}Оскверненным лесом{/link} и {link:winterspring}Зимними Ключами{/link}, и стерегут их от всякого пришельца.]=],
		},
		{
			title = "Недоверчивый народ",
			text = [=[Древобрюхи доверяют очень немногим. Многие путники теперь убивают любого {link:furbolgs}фурболг{/link}а, какого увидят, не спрашивая, друг он или враг. Древобрюхи извлекли из этого урок. Они привечают лишь тех, кто проявил себя в борьбе с оскверненными племенами — Мертвым Лесом из Оскверненного леса и Зимней Спячкой из Зимних Ключей. Им горько сражаться с собственной родней, но они сражаются. Король {link:magni-bronzebeard}Магни{/link} из {link:ironforge}Стальгорн{/link}а и вождь Орды в прошлом оба пытались найти к ним путь.]=],
		},
		{
			title = "Их надежда",
			text = [=[Древобрюхи верят, что {link:furbolgs}фурболг{/link}ами Зимней Спячки правит демон. Если его уничтожить, исцеление племени Зимней Спячки могло бы начаться, и Крепость была бы в безопасности на годы вперед.]=],
		},
	},
})

